def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_c = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1

    w = n if n < 10 else 10
    recent = history[-w:]
    recent_opp_c = 0
    recent_opp_d = 0
    recent_my_d = 0
    for m, o in recent:
        if o == 'C':
            recent_opp_c += 1
        else:
            recent_opp_d += 1
        if m == 'D':
            recent_my_d += 1

    cooperative = opp_c * 2 > n
    recent_coop = recent_opp_c * 5 >= 3 * w
    can_forgive = cooperative or (recent_my_d >= 2 and recent_coop)

    if opp_c == 0:
        return 'D'
    if n >= 6 and opp_c <= 1:
        return 'D'
    if n >= 12 and opp_c * 2 <= n and recent_my_d <= 3:
        return 'D'
    if n >= 25 and opp_c * 5 <= 2 * n and not can_forgive:
        return 'D'
    if recent_opp_c == 0 and n >= 5 and recent_my_d <= 2:
        return 'D'
    if n >= 30 and recent_opp_c * 5 <= 2 * w and recent_my_d <= 2:
        return 'D'

    after_my_d_c = 0
    after_my_d_d = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                after_my_d_c += 1
            else:
                after_my_d_d += 1

    exploitable = (
        opp_c * 4 >= 3 * n and
        recent_opp_c * 4 >= 3 * w and
        after_my_d_c >= 2 and
        after_my_d_d == 0 and
        n >= 25
    )

    if opp_last == 'D':
        if my_last == 'D':
            if can_forgive:
                return 'C'
            return 'D'

        if n >= 2 and history[-2][0] == 'D':
            if can_forgive:
                return 'C'

        if (
            opp_c * 10 >= 9 * n and
            recent_opp_d <= 1 and
            after_my_d_d <= 1 and
            n >= 6
        ):
            return 'C'

        return 'D'

    if exploitable:
        return 'D'

    return 'C'
